WITH months AS (SELECT DISTINCT CAST(date_trunc('month', date_day) AS DATE) AS month_start FROM {{ ref('time_spine') }}), member_months AS (SELECT m.member_id, mo.month_start FROM {{ ref('members') }} m CROSS JOIN months mo), valid_orders AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), monthly_orders AS (SELECT member_id, month_start, COUNT(*) AS valid_order_count FROM valid_orders GROUP BY member_id, month_start) SELECT mm.member_id, mm.month_start, COALESCE(mo.valid_order_count, 0) AS valid_order_count, mm.member_id || '|' || CAST(mm.month_start AS VARCHAR) AS member_month_key FROM member_months mm LEFT JOIN monthly_orders mo ON mm.member_id = mo.member_id AND mm.month_start = mo.month_start